const MACHINE_EPS: i32 = 2;

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // First check whether every element's imaginary part is "close to zero"
    // i.e., |imag| <= tol * MACHINE_EPS.
    let all_close = arr
        .iter()
        .all(|c| c.imag.abs() <= tol.saturating_mul(MACHINE_EPS));

    if all_close {
        // If every imaginary part is close to zero, zero them out.
        arr.into_iter()
            .map(|c| Complex { real: c.real, imag: 0 })
            .collect()
    } else {
        // Otherwise, return the original array unchanged.
        arr
    }
}